def build_agent(sandbox):
    # Main hull: large enough to ensure sufficient buoyancy
    hull = sandbox.add_beam(x=5.0, y=1.0, width=2.0, height=1.0, density=300.0)
    sandbox.set_material_properties(hull, restitution=0.1)
    return hull


def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x()
    target_x = 26.0

    # Obstacle locations
    obstacles = [(14.0, 0.88), (17.0, 0.90), (20.0, 0.92)]
    near_obstacle = any(abs(front_x - ox) < 1.5 for ox, oy in obstacles)

    # Thrust cooldown tracking
    if not hasattr(agent_action, 'thrust_cooldown'):
        agent_action.thrust_cooldown = 0

    if agent_action.thrust_cooldown > 0:
        agent_action.thrust_cooldown -= 1

    # Apply thrust
    if agent_action.thrust_cooldown <= 0:
        thrust = 520.0
        velocity = agent_body.linearVelocity.x

        # Throttle down if moving too fast
        if velocity > 3.0:
            thrust *= 0.2
        elif velocity > 2.0:
            thrust *= 0.5

        # Reduce thrust near obstacles
        if near_obstacle:
            thrust *= 0.5

        sandbox.apply_force(agent_body, thrust, 0, step_count=step_count)
        agent_action.thrust_cooldown = 18

    # Steering around obstacles
    if near_obstacle:
        for ox, oy in obstacles:
            if abs(front_x - ox) < 1.5:
                if front_x < ox:
                    # Turn left to avoid obstacle
                    sandbox.apply_force(agent_body, -100, 0, step_count=step_count)
                else:
                    # Turn right to avoid obstacle
                    sandbox.apply_force(agent_body, -100, 0, step_count=step_count)
                break  # Only steer for the nearest obstacle

    # Stop if target is reached
    if front_x >= target_x:
        agent_body.linearVelocity = (0, 0)
        agent_body.angularVelocity = 0
